44			t.Errorf("line = %d, want 5", inputErr.Line)
45		}
46		if !strings.Contains(inputErr.Reason, "partition 1") || !strings.Contains(inputErr.Reason, "2000") {
47			t.Errorf("reason = %q, want it to name partition 1 and boundary 2000", inputErr.Reason)
48		}
49		if got != want {
50			t.Fatalf("prior output must be retained on failed resume, got %q", got)
