317	// A partition that goes idle before ever reporting has no previous watermark:
318	// its resume only has to reach the current effective watermark. The resume
319	// recomputes the effective watermark as the min and never re-emits windows
320	// already closed while the partition was idle.
321	func TestAggregateIdleNeverReportedResume(t *testing.T) {
322		input := strings.Join([]string{
323			`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
324			`{"type":"event","key":"k","time":1100,"value":3,"partition":0}`,
325			`{"type":"idle","partition":1}`,                  // p1 never reported; effective still unknown
326			`{"type":"watermark","time":9000,"partition":0}`, // active set {p0}: closes both windows
327			`{"type":"watermark","time":9000,"partition":1}`, // resume never-reported p1: min = 9000
